  /// `secrets: inherit` as the PAT passthrough instead — the rule is
  /// per-callee, asserted below.
  final explicitSecretStubs = <String, String>{
    'ai-teammate.yml': teammate,
    'machine-sm.yml': sm,
    'machine-merge.yml': merge,
  };
